source_files.return_paths.py:
def status_label(task):
    if task["done"]:
        return "done"
    if task.get("minutes") is None:
        return "unknown"
    return "pending"


def announce(title):
    print(f"Ready: {title}")


def maybe_announce(title):
    if not title:
        return
    print(f"Ready: {title}")


print(status_label({"done": True, "minutes": None}))
print(status_label({"done": False, "minutes": None}))
print(status_label({"done": False, "minutes": 0}))
result = announce("Read")
print(result)
print(maybe_announce(""))

source_files.argument_binding.py:
def replace_local(task):
    task = {"title": "Local", "tags": []}
    return task


def add_topic(task, topic):
    task["tags"].append(topic)


original = {"title": "Read", "tags": ["python"]}
replacement = replace_local(original)
print(original["title"])
print(replacement["title"])
print(replacement is original)
result = add_topic(original, "functions")
print(result)
print(original["tags"])

